L34_1 = "알고 있을 텐데, 소령. 쐐기에 몸을 관통당했네."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "わかっているだろう、少佐。楔が身体を貫いたんだ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I'm sure you know why, Major. He was impaled by the Wedge."
L33_1.m_Talk_ENG = L34_1
L34_1 = "你應該很清楚，少校。他的身體已經被侵蝕釘穿透了。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ฉันเชื่อว่าคุณเองรู้ว่าทำไม ผู้พัน เขาถูกเสียบลึกขนาดนั้น"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi chắc rằng cô biết tại sao, Thiếu tá. Anh ấy đã bị Cái Nêm đâm vào người."
L33_1.m_Talk_VTN = L34_1
L34_1 = "你应该很清楚，少校。他的身体已经被侵蚀钉穿透了。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Du solltest wissen, warum ich das getan habe, Major. Er wurde von einem Verderbniskeil aufgespießt."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je suis sûre que tu sais pourquoi, major. Il a été empalé par la bestiole."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EXILER_ACT2_INTERUDE1@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5500201
L34_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "COMMANDER_EXILER_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "운 좋게 살아봤자, 급성 침식 증후군으로 인해 얼마 안 가 침식체가 되어버리겠지."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "運よく助かっても、そのうち急性侵食症候群によって侵食体になってしまうだろう。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Even if he somehow makes it through, he'll turn into a C.O. soon due to the acute Corruption Syndrome."
L34_1.m_Talk_ENG = L35_1
L35_1 = "就算運氣好活下來，也會因急性侵蝕症候群，很快變成侵蝕體。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ถึงเขาจะรอดไปได้ แต่สุดท้ายเขาก็จะกลายเป็นวัตถุคอร์รัปต์ในไม่ช้า  พวกนี้อาการคอร์รัปชั่นจะแสดงอาการรุนแรงขึ้นเรื่อยๆ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Ngay cả khi anh ta bằng cách nào đó vượt qua được, anh ta sẽ sớm trở thành V.T.A.M. do Hội chứng Ăn Mòn cấp tính."
L34_1.m_Talk_VTN = L35_1
L35_1 = "就算运气好活下来，也会因急性侵蚀症候群，很快变成侵蚀体。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Selbst wenn er es irgendwie geschafft hätte, zu überleben, wäre er aufgrund des akuten Verderbnissyndroms innerhalb kürzester Zeit zu einem C. O. mutiert."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Même s'il survit d'une manière ou d'une autre, il se changera en O.C. à cause du syndrome de Corruption aigüe."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EXILER_ACT2_INTERUDE1@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5500201
L35_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "COMMANDER_EXILER_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "그리고 스스로의 의지와 관계없이 사람을 죽일 걸세."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "そして自らの意思とは無関係に、人々を殺戮することになる。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Then, he'll have no control and start killing people."
L35_1.m_Talk_ENG = L36_1
L36_1 = "然後，他會控制不了自己的意識開始殺害人類。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "จากนั้นเขาก็จะควบคุมตัวเองไม่ได้และเริ่มฆ่าคนอื่นตาย"
L35_1.m_Talk_THA = L36_1
L36_1 = "Sau đó, anh ta sẽ mất kiểm soát và bắt đầu giết người."
L35_1.m_Talk_VTN = L36_1
L36_1 = "然后，他会控制不了自己的意识并开始杀害人类。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Dann hätte er jegliche Kontrolle über sich selbst verloren und angefangen, Menschen zu töten."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Après quoi, il ne pourra plus se contrôler et se mettra à tuer des gens."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
