L37_1 = "COMMANDER_EXILER_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "이 세계가 끝나버리는 그 순간까지 계속."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "この世界が終わる瞬間まで、ずっとだ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "And he won't stop until the day this world ends."
L36_1.m_Talk_ENG = L37_1
L37_1 = "直到這個世界徹底毀滅的那一刻為止。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เขาไม่มีทางหายจนกว่าโลกนี้จะถึงตอนจบ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Và anh ấy sẽ không dừng lại cho đến ngày thế giới này kết thúc."
L36_1.m_Talk_VTN = L37_1
L37_1 = "直到这个世界彻底毁灭的那一刻为止。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Und er hätte bis zum letzten Moment dieser Welt nicht damit aufgehört."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Et il ne s'arrêtera que le jour où ce monde disparaîtra."
L36_1.m_Talk_FRA = L37_1
