L41_1 = "R_M_I"
L40_1.m_Pos = L41_1
L41_1 = "그, 그렇다고 하더라도 이래서는 앞서간 대원들을 볼 면목이……."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "で、ですが、これでは先立った隊員たちに面目が……"
L40_1.m_Talk_JPN = L41_1
L41_1 = "B-but even so, I will be ashamed to face the other troops who fell before me..."
L40_1.m_Talk_ENG = L41_1
L41_1 = "即，即便如此，我拿什麼面對那些犧牲的隊員們……"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ต-แต่ยังไง ฉันก็ละอายใจที่เห็นสมาชิกคนอื่นๆ ตายต่อหน้าต่อตาฉัน..."
L40_1.m_Talk_THA = L41_1
L41_1 = "N-nhưng ngay cả như vậy, tôi sẽ xấu hổ khi đối mặt với các thành viên khác đã ngã xuống trước tôi..."
L40_1.m_Talk_VTN = L41_1
L41_1 = "即、即便如此，我拿什么面对那些牺牲的队员们……"
L40_1.m_Talk_SCN = L41_1
L41_1 = "A-aber trotzdem werde ich mich schämen, den anderen Truppen gegenüberzutreten, die vor mir gefallen sind ..."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Qu-Quoi qu'il en soit, je n'ai pas le courage de faire face à mes camarades tombés au combat..."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EXILER_ACT2_INTERUDE1@41#Talk"
