L41_1.m_Crash = 10
L42_1 = "착각하지 말게."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "勘違いしないでくれ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Don't be mistaken."
L41_1.m_Talk_ENG = L42_1
L42_1 = "別搞錯了。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "อย่าโทษตัวเองสิ สารวัตร"
L41_1.m_Talk_THA = L42_1
L42_1 = "Đừng nhầm lẫn."
L41_1.m_Talk_VTN = L42_1
L42_1 = "别搞错了。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Du irrst dich."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Ne te méprends pas."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EXILER_ACT2_INTERUDE1@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5500201
L42_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "COMMANDER_EXILER_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "L"
L42_1.m_Pos = L43_1
L43_1 = "우리에게 필요한 건 죽은 자에 대한 추모나 감상 따위가 아니야."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "我々に必要なのは死者への弔いでも、感傷でもない。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "We do not need respect or mourning for the deceased at this time."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我們需要的不是對亡者的追悼和感傷。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ตอนนี้เราไม่มีเวลามาแสดงความเคารพหรือไว้อาลัยผู้เสียชีวิตนะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Chúng ta không cần sự kính trọng hay thương tiếc cho người đã khuất vào lúc này."
L42_1.m_Talk_VTN = L43_1
L43_1 = "我们需要的不是对亡者的追悼和感伤。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Was wir brauchen, ist weder die Erinnerung an noch die Wertschätzung der Toten."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Il n'est ni l'heure de commémorer nos morts ni de leur rendre hommage."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EXILER_ACT2_INTERUDE1@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 5500201
L43_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "COMMANDER_EXILER_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "L"
L43_1.m_Pos = L44_1
L44_1 = "필요한 건, 앞으로 더 많은 사람을 살리기 위한 실질적인 대책이지."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "必要なのは、この先少しでも多くの者を生かすための具体的な対策だ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "We need an effective plan to save more lives in the years to come."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我們需要的，是以後能讓更多人活下來的實際作為。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "พวกเราต้องวางแผนการที่มีประสิทธิภาพเพื่อช่วยปกป้องชีวิตของผู้คนให้มากขึ้น "
L43_1.m_Talk_THA = L44_1
L44_1 = "Chúng ta cần một kế hoạch hiệu quả để cứu nhiều mạng sống hơn trong những năm tới."
L43_1.m_Talk_VTN = L44_1
L44_1 = "我们需要的，是以后能让更多人活下来的实际性措施。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Was wir brauchen, sind praktische Maßnahmen, um in Zukunft mehr Menschen retten zu können."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Nous avons besoin d'un plan efficace pour sauver plus de vies dans les années à venir."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
