L46_1 = "따라오게. 자네에게 한 가지 제안을 하고 싶군."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ついてきてくれ。君に一つ提案がしたい。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Follow me. I want to make you a proposition."
L45_1.m_Talk_ENG = L46_1
L46_1 = "跟我來。我有個提議。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ทำตามฉัน ในวิธีนี้ที่ฉันเสนอให้คุณพิจารณา"
L45_1.m_Talk_THA = L46_1
L46_1 = "Theo tôi. Tôi có một đề nghị cho cô."
L45_1.m_Talk_VTN = L46_1
L46_1 = "跟我来。我有个提议。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Folge mir. Ich möchte dir gerne einen Vorschlag machen."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Suis-moi. J'ai une proposition à te faire."
L45_1.m_Talk_FRA = L46_1
