L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 5500201
L48_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "UNIT_IDLE"
L48_1.m_Face = L49_1
L48_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L49_1 = "LONE_EXILER_NPC_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "C_R_M_I"
L48_1.m_Pos = L49_1
L49_1 = "일단, 두 사람 다 급한 고비는 넘겼어."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ひとまず、二人とも峠は越えたよ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "For the time being, these two are over the hump."
L48_1.m_Talk_ENG = L49_1
L49_1 = "好了，她們二個都已經渡過危險期。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ตอนนี้ทั้งสองอยู่ในการช่วยเหลือจากผมแล้ว"
L48_1.m_Talk_THA = L49_1
L49_1 = "Hiện tại, hai người này đang vượt qua cơn nguy kịch."
L48_1.m_Talk_VTN = L49_1
L49_1 = "好了，她们两个都已经渡过了生命危险期。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Die beiden sind fürs Erste über den Berg."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ces deux-là ne sont plus dans un état critique."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EXILER_ACT2_INTERUDE1@49#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 5500201
L49_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "LONE_EXILER_NPC_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "응급치료는 해두었지만, 비위생적인 환경에서 수술을 시도한 건 자살 행위에 가까워."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "応急手当ては施したけど、非衛生的な環境下での手術は自殺行為に等しいんだ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I did some urgent care, but performing surgery in such an unsanitary environment was practically suicide."
L49_1.m_Talk_ENG = L50_1
L50_1 = "雖然做了應急治療，但在有菌環境下進一步進行手術無疑是自殺。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ผมจะดูแลเคสนี้อย่างดี แต่การผ่าตัดในสภาพไม่ถูกสุขลักษณะแบบนี้ แทบจะเป็นการฆ่าพวกเขาตายได้เลยนะครับ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi đã thực hiện vài sự chăm sóc khẩn cấp, nhưng thực hiện phẫu thuật trong một môi trường mất vệ sinh như vậy gần như là tự sát."
L49_1.m_Talk_VTN = L50_1
L50_1 = "虽然做了应急治疗，但在有菌环境下进一步进行手术无异于自杀。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ich habe eine Notfallbehandlung durchgeführt, aber eine Operation in solch einer unhygienischen Umgebung durchzuführen wäre reiner Selbstmord."
L49_1.m_Talk_DEU = L50_1
L50_1 = "J'ai fait ce que j'ai pu en urgence, mais effectuer une intervention chirurgicale dans un environnement aussi insalubre était pratiquement du suicide."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EXILER_ACT2_INTERUDE1@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 5500201
L50_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_DESPAIR"
L51_1 = "LONE_EXILER_NPC_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "당장 사령부 본부로 가서 정식으로 치료를 받아야 해."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "今すぐに司令本部に移送して、正式な治療を受けさせるべきだよ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "They need to be transported to HQ and get proper medical treatment."
L50_1.m_Talk_ENG = L51_1
L51_1 = "需要馬上帶她們去司令總部接受正式的治療。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "พวกเขาจะต้องถูกส่งตัวไปที่ศูนย์บัญชาการและให้พวกเขาได้รับการรักษาที่เหมาะสมนะครับ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Họ cần được chuyển đến Trụ Sở và được điều trị y tế thích hợp."
L50_1.m_Talk_VTN = L51_1
L51_1 = "需要马上带她们去司令总部接受正式的治疗。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Sie müssen zum Hauptquartier transportiert werden und eine angemessene medizinische Behandlung erhalten."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Elles doivent être transportées au QG et recevoir des soins appropriés."
L50_1.m_Talk_FRA = L51_1
