L3_1.m_Pos = L4_1
L3_1.m_Crash = 10
L4_1 = "후후, 비위생적인 환경이라 미안하군. 아무래도 꽤나 연식이 있는 배라서 말이지."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "ふふ、非衛生的な環境で申し訳ない。この艦船もだいぶ長く使っているからな。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Ha ha, sorry about the unsanitary conditions. It's an old ship, after all."
L3_1.m_Talk_ENG = L4_1
L4_1 = "呵呵，非常抱歉。這艘船畢竟也有些年紀了。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "อืม ขออภัย กับสภาพยานที่ไม่สะอาด เพราะมันเป็นแค่ยานเก่าๆเอง"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ha ha, xin lỗi về mất vệ sinh. Dù sao thì nó là một con tàu cũ."
L3_1.m_Talk_VTN = L4_1
L4_1 = "呵呵，非常抱歉。这艘船毕竟也有些年头了。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Haha, entschuldige bitte die unhygienische Umgebung. Es ist schließlich ein recht altes Schiff."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Ha ha, désolée pour les conditions insalubres. C'est un vieux vaisseau, après tout."
L3_1.m_Talk_FRA = L4_1
