L6_1 = "LONE_EXILER_NPC_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L5_1.m_Crash = 10
L6_1 = "아, 아니 그런 뜻은 아니었는데…… 요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "い、いや、そういうつもりで言ったわけじゃ……"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Oh, well, I didn't mean it like... that."
L5_1.m_Talk_ENG = L6_1
L6_1 = "不，不會，我不是那個……意思。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เอิม ผมไม่ได้หมายความว่าแบบนั้นนะครับ..."
L5_1.m_Talk_THA = L6_1
L6_1 = "Ồ, tôi không có ý đó như... thế."
L5_1.m_Talk_VTN = L6_1
L6_1 = "不，不会，我不是那个……意思。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ah, nein. So habe ich das nicht gemeint ..."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Oh, eh bien, ce n'est pas ce que je voulais dire..."
L5_1.m_Talk_FRA = L6_1
