L6_1.m_Crash = 20
L7_1 = "<color=#ffd34c>아이기스</color>, 항행 궤도 수정. 목표는 제1 지구 방위군 사령 본부."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "<color=#ffd34c>アイギス</color>、航行軌道を修正。目標は第1地区の防衛軍指令本部。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "<color=#ffd34c>Aegis</color>, correcting navigation trajectory. Destination: Defense Force HQ, 1st District."
L6_1.m_Talk_ENG = L7_1
L7_1 = "<color=#ffd34c>埃癸斯</color>，調整航行軌道。目的地為第一區保衛軍司令總部。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "<color=#ffd34c>ยานเอจิส</color> กำลังแก้ไขวิถีการนำทาง ปลายทาง:ศูนย์บัญชาการกองกำลังป้องกัน เขตที่ 1"
L6_1.m_Talk_THA = L7_1
L7_1 = "<color=#ffd34c>Aegis</color>, điều chỉnh quỹ đạo điều hướng. Điểm đến: Trụ Sở Lực Lượng Phòng Vệ, Quận 1."
L6_1.m_Talk_VTN = L7_1
L7_1 = "<color=#ffd34c>埃癸斯</color>，调整航行轨道。目的地为第1区防卫军司令总部。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "<color=#ffd34c>Aegis</color>, korrigiere die Navigationsbahn. Ziel: Hauptquartier der Verteidigungsstreitkräfte im 1. Bezirk."
L6_1.m_Talk_DEU = L7_1
L7_1 = "<color=#ffd34c>Aegis</color>, correction de la trajectoire de navigation. Destination : QG des Forces de défense, 1er district."
L6_1.m_Talk_FRA = L7_1
