L16_1 = "무엇보다도 나는 인공지능을 그다지 신뢰하지 않아서 말이지."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "何より、私はあまり人工知能を信頼しないのでね。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "But above all, I do not trust AIs that much."
L15_1.m_Talk_ENG = L16_1
L16_1 = "主要是我並不太信任人工智慧。"
