L17_1 = "UNIT_SERIOUS"
L16_1.m_Face = L17_1
L17_1 = "COMMANDER_EXILER_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "L"
L16_1.m_Pos = L17_1
L17_1 = "간단히 말하자면 이 함선, 아이기스는 나와 직접적으로 연결되어 있다네."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "簡単に説明すると、この艦船、アイギスは私と直に繋がっているのだ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Simply put, this ship, Aegis, is directly connected to me."
L16_1.m_Talk_ENG = L17_1
L17_1 = "簡單說，埃癸斯這艘艦船和我的意識共通。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "พูดง่ายๆ ก็คือ ยานเอจิสลำนี้ มันเชื่อมต่อกับฉันโดยตรง"
L16_1.m_Talk_THA = L17_1
L17_1 = "Nói một cách đơn giản, con tàu Aegis này được kết nối trực tiếp với tôi."
L16_1.m_Talk_VTN = L17_1
L17_1 = "简单点说，埃癸斯这艘舰船和我的意识共通。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Einfach ausgedrückt, dieses Schiff, Aegis, ist direkt mit mir verbunden."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Autrement dit, ce vaisseau, Aegis, est directement connecté à moi."
L16_1.m_Talk_FRA = L17_1
