L18_1 = "EXILER_ACT2_INTERUDE1@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5500201
L17_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "UNIT_IDLE"
L17_1.m_Face = L18_1
L18_1 = "COMMANDER_EXILER_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "L"
L17_1.m_Pos = L18_1
L18_1 = "함장인 내가 죽으면 모든 시스템이 영구 동결되고, 아이기스 무기고의 장비들은 분자 단위로 파기되도록 설정되어 있지."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "艦長である私が死ねばすべてのシステムは永久に凍結され、アイギスの武器庫に積まれている装備は分子単位に分解されるよう設定されている。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "All systems will go into permanent lockdown if I, the captain, die. Also, all the gear in the arsenal will be dismantled to a molecular level."
L17_1.m_Talk_ENG = L18_1
L18_1 = "作為艦長的我要是死了，所有系統都會永久凍結，埃癸斯武器庫裡的裝備也會被分解為分子銷毀掉。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ระบบทั้งหมดจะเข้าสู่การล็อคถาวร ถ้าหากว่าฉันตายไป และนอกจากนี้อุปกรณ์ทั้งหมดในคลังแสงก็จะถูกแปลงสภาพกลายเป็นระดับโมเลกุลอีกด้วย"
L17_1.m_Talk_THA = L18_1
L18_1 = "Tất cả các hệ thống sẽ bị khóa vĩnh viễn nếu thuyền trưởng là tôi chết. Ngoài ra, tất cả các thiết bị trong kho vũ khí sẽ được phân rã ở cấp độ phân tử."
L17_1.m_Talk_VTN = L18_1
L18_1 = "作为舰长的我要是死了，所有系统都会永久冻结，埃癸斯武器库里的装备也会被分解为分子销毁掉。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Alle Systeme würden dauerhaft gesperrt, wenn ich, der Kapitän, sterben sollte. Außerdem würde die gesamte Ausrüstung in der Waffenkammer in molekulare Einzelteile zerfallen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Tous les systèmes se verrouilleront de manière permanente si moi, son capitaine, venait à mourir. Sans oublier que tout l'équipement de l'arsenal sera démantelé au niveau moléculaire."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EXILER_ACT2_INTERUDE1@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 5500201
L18_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L19_1 = "R"
L18_1.m_Pos = L19_1
L19_1 = "연결되어 있다고? 분자단위로 파기? 대체 그게 무슨 뜻이죠?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "繋がっている？　分子単位に分解？　いったいどういう意味ですか？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Connected? Dismantled to a molecular level? What does that even mean?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "意識共通？分解成分子？到底是什麼意思？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ชะ เชื่อมต่อหรอ? แตกสลายเป็นระดับโมเลกุล? นั่นหมายความว่าไง?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Kết nối? Phân rã đến mức độ phân tử? Điều đó có nghĩa là gì?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "意识共通？分解成分子？到底是什么意思？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Mit Ihnen verbunden? In molekulare Einzelteile zerfallen? Was bedeutet das überhaupt?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Connecté ? Démantelé à un niveau moléculaire ? Qu'est ce que ça veut dire ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EXILER_ACT2_INTERUDE1@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 5500201
L19_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L20_1 = "R"
L19_1.m_Pos = L20_1
L20_1 = "아니, 그보다 안토노프 행정관, 당신은 대체 누구입니까?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "いいえ、それよりもアントノフ行政官、あなたはいったい誰なんですか？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Above all, Officer Antonov, who are you really?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "不，安東諾夫行政官，你到底是誰？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "นอกจากนี้ เจ้าหน้าที่แอนโทนอฟ แท้จริงแล้วเธอเป็นใครกันแน่?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Nhưng trước đó, sĩ quan Antonov, cô thực sự là ai?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "不，安东行政官，你到底是谁？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Die wichtigste Frage ist aber eigentlich: Wer sind Sie wirklich, Verwaltungsbeamtin Antonow? Sie duzen uns alle plötzlich und reden auch irgendwie ganz anders als zuvor ..."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Officier Antonov, mais qui êtes-vous réellement ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EXILER_ACT2_INTERUDE1@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5500201
L20_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L21_1 = "R"
L20_1.m_Pos = L21_1
L21_1 = "이 말도 안 되는 거대 함선과 무기들로 우리 세계에서 대체 무슨 짓을 할 작정이었죠?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "このとてつもない巨大艦船や武器を私たちの世界に持ち込んだ目的は何なんですか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "What were you planning to do to our world with this ridiculously massive ship and its weapons?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "如此不可思議的巨型艦船和還有各式武器，你打算在我們世界裡做什麼？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เธอวางแผนจะทำอะไรกับโลกของเรา กับยานยักษ์นี้และคลังอาวุธพวกนี้อีก? บอกฉันมานะ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Cô định làm gì với thế giới của chúng tôi với con tàu khổng lồ lố bịch này và vũ khí của nó?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "如此不可思议的巨型舰船和还有各式武器，你打算在我们世界里做什么？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Was hatten Sie mit diesem unglaublich riesigen Schiff und seinen Waffen in unserer Welt vor?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Que prévoyiez-vous de faire à notre monde avec un vaisseau de cette taille et avec toutes ces armes ?"
L20_1.m_Talk_FRA = L21_1
