L24_1.m_Talk_VTN = L25_1
L25_1 = "这个世界的<color=#ffd34c>玛丽亚·安东</color>已经战死了吗？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ist die <color=#ffd34c>Maria Antonow</color> dieser Welt bereits verstorben?"
L24_1.m_Talk_DEU = L25_1
