L29_1 = "R"
L28_1.m_Pos = L29_1
L28_1.m_Crash = 10
L29_1 = "그게 누구죠? 제가 아는 한, 그런 사람은 존재하지 않습니다."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "それは誰ですか？　私の知る限りでは、そんな人は存在しません。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Who may that be? As far as I know, no one with that name exists."
L28_1.m_Talk_ENG = L29_1
L29_1 = "那是誰？據我所知，這個世界沒有這個人。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เขาคือใคร ? เท่าที่ฉันรู้ไม่มีใครที่ฉันรู้จักในชื่อนี้"
L28_1.m_Talk_THA = L29_1
L29_1 = "Đó có thể là ai chứ? Theo như tôi biết, không có ai có tên đó tồn tại."
L28_1.m_Talk_VTN = L29_1
L29_1 = "那是谁？据我所知，这个世界没有这个人。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Wer soll das sein? Soweit ich weiß, existiert niemand mit diesem Namen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "J'ignore de qui il s'agit. Pour autant que je sache, personne ne portant ce nom n'existe."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EXILER_ACT2_INTERUDE1@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 5500201
L29_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "UNIT_PRIDE"
L29_1.m_Face = L30_1
L30_1 = "COMMANDER_EXILER_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "L"
L29_1.m_Pos = L30_1
L29_1.m_Crash = 20
L30_1 = "후후, 그런가. 운명도 참 짓궂군."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "ふふ、そういうことか。運命とは実に皮肉なものだな。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Ha ha, is that so? Fate can be so cruel."
L29_1.m_Talk_ENG = L30_1
L30_1 = "呵呵，是嗎？命運真是太討厭了。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฮ่าฮ่า อย่างนั้นเหรอ? เนี๊ยโชคชะตาช่างโหดร้ายจริงๆ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Ha ha, vậy sao? Số phận có thể rất tàn nhẫn."
L29_1.m_Talk_VTN = L30_1
L30_1 = "呵呵，是吗。命运真是太讨厌了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Haha, ist das so? Das Schicksal kann so grausam sein."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Ha ha, vraiment ? Le destin peut être si cruel."
L29_1.m_Talk_FRA = L30_1
