L31_1 = "EXILER_ACT2_INTERUDE1@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5500201
L30_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_DESPAIR"
L31_1 = "COMMANDER_EXILER_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "L"
L30_1.m_Pos = L31_1
L31_1 = "대원들의 목숨과 맞바꿔 도달한 오랜 항해의 끝이……"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "長い航海の中で、隊員たちの命と引き換えにたどり着いた先というのが……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "At the end of my long voyage, reached at the cost of the crew members' lives..."
L30_1.m_Talk_ENG = L31_1
L31_1 = "隊員們用生命換來的，漫長航行的盡頭……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "สุดท้ายแล้วการเดินทางที่ยาวนานของฉัน ก็คร่าชีวิตลูกเรือในยานเองสินะ..."
L30_1.m_Talk_THA = L31_1
L31_1 = "Vào cuối chuyến đi dài của tôi, tôi đã phải trả giá bằng mạng sống của các thành viên phi hành đoàn…"
L30_1.m_Talk_VTN = L31_1
L31_1 = "队员们用生命换来的、漫长航行的尽头……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Am Ende meiner langen Reise, konnte ich endlich mein Ziel erreichen ... Aber nur auf Kosten des Lebens der anderen Besatzungsmitglieder ..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "À la fin de mon long voyage et au prix de la vie des membres de mon équipage..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EXILER_ACT2_INTERUDE1@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5500201
L31_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "COMMANDER_EXILER_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "L"
L31_1.m_Pos = L32_1
L31_1.m_Crash = 10
L32_1 = "대적자도, 세계를 구할 영웅도 없는 이 따위 나약한 세계였다니."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "敵対者も、世界を救う英雄もいない、こんな軟弱な世界だったとは。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I'm met with such a weak world with no Antagonist and no heroes."
L31_1.m_Talk_ENG = L32_1
L32_1 = "竟是如此弱小世界，既沒有敵對者，也沒有拯救世界的英雄。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฉันพบกับโลกที่อ่อนแอ ซึ่งไม่มีศัตรูหรือฮีโร่สักคนเหลือเลย"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi đã gặp một thế giới yếu ớt như vậy, không có Kẻ Chống Đối và không có anh hùng."
L31_1.m_Talk_VTN = L32_1
L32_1 = "竟是没有敌对者，也没有拯救过人类的英雄的弱小世界。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Am Ende der Reise habe ich eine so schwache Welt entdeckt, in der es weder einen Antagonisten noch einen Helden gab."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Il fallait que je tombe sur un monde aussi faible sans Antagoniste et sans héros pour le sauver."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EXILER_ACT2_INTERUDE1@82#Talk"
