L41_1 = "L"
L40_1.m_Pos = L41_1
L41_1 = "이 단말기는 일종의 <color=#ffd34c>측정기</color>라네."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "この端末は<color=#ffd34c>測定器</color>のようなものだ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "This terminal is a kind of <color=#ffd34c>gauge</color>."
L40_1.m_Talk_ENG = L41_1
L41_1 = "這個終端機是一種<color=#ffd34c>測量儀</color>。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เทอร์มินัลนี้เป็นเครื่อง <color=#ffd34c>วัด</color> ชนิดหนึ่ง"
L40_1.m_Talk_THA = L41_1
L41_1 = "Thiết bị đầu cuối này là một loại <color=#ffd34c>máy đo</color>."
L40_1.m_Talk_VTN = L41_1
L41_1 = "这个终端机是一种<color=#ffd34c>测量仪</color>。"
