L41_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "COMMANDER_EXILER_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "L"
L41_1.m_Pos = L42_1
L42_1 = "침식파에 장기간 피폭된 토양을 검출하여, 파장을 분석, 해당 세계의 <color=#ffd34c>침식률</color>을 대략적인 수치로 표기해주지."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "侵食波に長期間晒され続けた土壌を検出し、波長を分析することで、その世界の<color=#ffd34c>侵食率</color>を大体の数字で表してくれる。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "It detects soil with long-term exposure to Corruption rays, analyzes the wavelength, and displays an approximate figure of the world's <color=#ffd34c>Corruption rate</color>."
L41_1.m_Talk_ENG = L42_1
L42_1 = "可以檢測被侵蝕波長時間輻射的土壤，然後通過分析波長，記錄該世界的<color=#ffd34c>侵蝕率</color>的大概數值。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "มันจะตรวจพื้นดินที่มีการปนเปื้อนของรังสีคอรัปต์ในระยะยาว แล้ววิเคราะห์ความยาวคลื่นออกมาทางตัวเลขโดยประมาณของ<color=#ffd34c>อัตราการคอรัปต์</color>ของโลก"
L41_1.m_Talk_THA = L42_1
L42_1 = "Nó phát hiện đất tiếp xúc lâu dài với tia Ăn Mòn, phân tích bước sóng và hiển thị con số gần đúng về <color=#ffd34c>Tỷ lệ Ăn Mòn</color> của thế giới."
L41_1.m_Talk_VTN = L42_1
L42_1 = "可以检测被侵蚀波长时间辐射的土壤，然后通过分析波长，记录相应世界的<color=#ffd34c>侵蚀率</color>的大概数值。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Es erkennt Böden, die über einen längeren Zeitraum Verderbniswellen ausgesetzt waren, analysiert die Wellenlänge und zeigt einen ungefähren Wert der weltweiten <color=#ffd34c>Verderbnisrate</color>."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Il détecte les sols ayant longuement été exposés aux rayons de Corruption, analyse la longueur d'onde et affiche une valeur approximative du <color=#ffd34c>taux de Corruption</color> de ce monde."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EXILER_ACT2_INTERUDE1@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5500201
