L42_1.m_CharStrID = L43_1
L43_1 = "L"
L42_1.m_Pos = L43_1
L43_1 = "오차는 있지만, 1이 넘는 수치는 보통 이면세계의 토양에서나 검출돼."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "誤差はあるが、通常は1を超える数値は裏世界の土壌でしか検出されない。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "There is a margin of error, but any figure over 1 is normally detected in the soil of Counterside."
L42_1.m_Talk_ENG = L43_1
L43_1 = "雖然存在誤差，但超過1的數值，一般只會在異界的土壤中被檢測到。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "มันอาจมีข้อผิดพลาดเล็กน้อย แต่โดยปกติแล้วตัวเลขที่มีค่ามากกว่า 1 มัน จะแสดงว่าตรวจพบในดินเคาน์เตอร์ไซด์"
L42_1.m_Talk_THA = L43_1
L43_1 = "Có một sai số, nhưng bất kỳ con số nào lớn hơn 1 thường được phát hiện trong vùng đất của Counterside."
L42_1.m_Talk_VTN = L43_1
L43_1 = "虽然存在误差，但超过1的数值，一般只会在异界的土壤中被检测到。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Es gibt zwar einen Fehlerspielraum, aber Werte über 1 werden meist nur im Boden von Counterside nachgewiesen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Bien sûr il y a une marge d'erreur, mais en règle générale tout taux supérieur à 1 est détecté dans le sol du Contremonde."
L42_1.m_Talk_FRA = L43_1
