L47_1 = 30
L46_1.m_Crash = L47_1
L47_1 = "헛소리하지 마세요! 우리 세계는 아직 멸망하지 않았습니다!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ふざけないでください！　私たちの世界はまだ滅んではいません！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Don't be ridiculous! Our world hasn't been destroyed yet!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "別胡說八道了！我們的世界還沒有滅亡！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ไร้สาระน่ะ! โลกของเรายังไม่ถูกทำลายซะหน่อย!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Đừng có lố bịch! Thế giới của chúng tôi vẫn chưa bị phá hủy!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "别胡说八道了！我们的世界还没有灭亡！"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Reden Sie doch keinen Unsinn! Unsere Welt wurde doch noch gar nicht zerstört!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ne soyez pas ridicule ! Notre monde n'a pas encore été détruit !"
L46_1.m_Talk_FRA = L47_1
