L50_1 = "UNIT_IDLE"
L49_1.m_Face = L50_1
L50_1 = "COMMANDER_EXILER_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "L"
L49_1.m_Pos = L50_1
L50_1 = "유감스럽지만 멸망하지 않은 세계가 이런 수치를 가리키는 이유는 한 가지뿐이야."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "残念だが、滅んでいない世界においてこのような数値が検出される理由は一つしかない。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I am sorry to tell you, but there is only one reason why a world with a Corruption rate like this has not collapsed yet."
L49_1.m_Talk_ENG = L50_1
L50_1 = "很遺憾，未滅亡的世界會顯示這樣的數值，理由只有一種。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฉันเสียใจที่ต้องบอกคุณแบบนี้ มีเหตุผลเดียวที่ทำให้โลกที่มีอัตราการคอรัปต์แบบนี้ ที่ยังไม่ล่มสลาย"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi rất tiếc phải nói với cô, nhưng chỉ có một lý do duy nhất khiến một thế giới có tỷ lệ Ăn Mòn như thế này vẫn chưa sụp đổ."
L49_1.m_Talk_VTN = L50_1
L50_1 = "很遗憾，未灭亡的世界会显示这样的数值，理由只有一种。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Es tut mir leid, dir das so sagen zu müssen, aber es gibt nur einen Grund, warum eine Welt mit einer solchen Verderbnisrate noch nicht zerstört wurde."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Je suis désolée de te le dire, mais il n'y a qu'une seule raison qui explique qu'un monde avec un taux de Corruption aussi élevé que celui-ci ne se soit pas encore effondré."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EXILER_ACT2_INTERUDE1@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 5500201
