L50_1.m_CharStrID = L51_1
L51_1 = "L"
L50_1.m_Pos = L51_1
L51_1 = "원래 멸망했어야 하는 세계가, 어떤 이유로 멸망을 회피한 거지."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "本来滅ぶはずだった世界が、何らかの要因により滅びから免れた。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "The world that was originally supposed to collapse somehow avoided it."
L50_1.m_Talk_ENG = L51_1
L51_1 = "本該滅亡的世界，因為某種原因而躲過滅亡。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ตามความจริงโลกควรจะล่มสลายไปนานแล้วแต่ไม่"
L50_1.m_Talk_THA = L51_1
L51_1 = "Thế giới mà ban đầu vốn phải sụp đổ đã tránh được bằng cách nào đó."
L50_1.m_Talk_VTN = L51_1
L51_1 = "本该灭亡的世界，因为某种原因而回避了灭亡。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Die Welt, die ursprünglich zerstört werden sollte, konnte aus irgendeinem Grund der Zerstörung entgehen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Ce monde qui était censé s'effondrer à l'origine a, d'une certaine manière, évité sa destruction."
L50_1.m_Talk_FRA = L51_1
