L3_1.m_Talk_JPN = L4_1
L4_1 = "But that operation bought us 20 years' worth of time!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "但那場作戰為我們世界爭取了20年的時間！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แต่ปฏิบัติการนั่นทำให้เราเสียเวลาไปตั้ง 20 ปี!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Nhưng tác chiến đó đã câu thêm cho chúng tôi thời gian 20 năm!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "但那场作战为我们世界争取了20年的时间！"
L3_1.m_Talk_SCN = L4_1
