L5_1.m_fTalkTime = 0.03
L6_1 = "いや、そもそもの前提が間違っている。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "No, your premise was wrong from the start."
L5_1.m_Talk_ENG = L6_1
L6_1 = "不，從一開始就錯了。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ไม่คิดหรอว่าการคาดการของคุณผิดตั้งแต่แรกแล้ว"
L5_1.m_Talk_THA = L6_1
L6_1 = "Không phải, tiền đề của cô đã sai ngay từ đầu."
L5_1.m_Talk_VTN = L6_1
L6_1 = "不，你的设想一开始就错了。"
