L7_1 = "COMMANDER_EXILER_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "그 20년이라는 형편 좋은 기준은 대체 뭘 근거로 세운 건가?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "その20年という都合の良い数字の根拠はいったい何なのだ？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "On what grounds did you conveniently decide it was 20 years?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "到底是以什麼標準來判斷這20年就是好的呢？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ทำไม คุณถึงคิดว่ามันต้องใช้เวลา 20 ปี?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Trên cơ sở nào mà cô tiện phán đoán đó là 20 năm?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "到底是以什么基准来判断这20年就是好的呢？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Wie seid ihr überhaupt auf 20 Jahre gekommen? Mit welcher Begründung könnt ihr diesen Zeitraum rechtfertigen?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Sur quelles données vous êtes-vous basés pour décider qu'il s'agissait de 20 ans ? Plutôt pratique, n'est-ce pas ?"
L6_1.m_Talk_FRA = L7_1
