L8_1.m_Face = "UNIT_LAUGH"
L9_1 = "LONE_EXILER_NPC_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L8_1.m_Crash = 10
L9_1 = "어, 저기 그건 일단 제가 분석한 고치의 부화 기간이긴 한데요…… 하, 하하."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "あっ、それは一応僕が分析した、繭の孵化にかかる期間なんですけど……は、はは。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Well, I was the one who found out that it took that long for a cocoon to hatch... Ha, ha ha."
L8_1.m_Talk_ENG = L9_1
L9_1 = "呃，那個，首先是我分析出了繭的孵化期……哈，哈哈。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "การวิเคราะห์นั่น ผมเป็นคนค้นพบ เพราะรังไหมพวกนั้นจะใช้เวลาประมาณนั้นจึงจะฟักออกมา... ฮ่า ฮ่า"
L8_1.m_Talk_THA = L9_1
L9_1 = "Chà, tôi là người phát hiện ra rằng kén nở lâu như vậy... Ha, ha ha."
L8_1.m_Talk_VTN = L9_1
L9_1 = "呃，那个，首先是我分析出了茧的孵化期……哈、哈哈。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Nun, ich war derjenige, der herausgefunden hat, dass es so lange dauert, bis ein Kokon schlüpft ... Hahaha."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Eh bien, c'est moi qui ai découvert qu'il fallait 20 ans à un cocon pour éclore... Ha ha ha."
L8_1.m_Talk_FRA = L9_1
