L12_1 = "UNIT_IDLE"
L11_1.m_Face = L12_1
L12_1 = "COMMANDER_EXILER_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "L"
L11_1.m_Pos = L12_1
L12_1 = "결과가 확정된 세계에서 그 과정 같은 건 중요하지 않아."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "結果が確定してしまった世界では、もはや過程など意味を持たない。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Process means nothing in a world where the outcome is fixed."
L11_1.m_Talk_ENG = L12_1
L12_1 = "對於結局已定的世界，過程並不重要。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "กระบวนการไม่มีความหมายสำหรับโลกที่มีผลลัพธ์แล้วและกำลังรับแก้ไขอยู่"
L11_1.m_Talk_THA = L12_1
L12_1 = "Quá trình chẳng có ý nghĩa gì trong một thế giới đã có kết quả được định sẵn."
L11_1.m_Talk_VTN = L12_1
L12_1 = "对于结局已定的世界，过程并不重要。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "In einer Welt, in der das Ergebnis bereits feststeht, ist der Prozess nicht wichtig."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Peu importe ce que vous tentez, tout processus est inutile dans un monde dont l'issue est déjà décidée."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EXILER_ACT2_INTERUDE1@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 5500201
L12_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "COMMANDER_EXILER_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "L"
L12_1.m_Pos = L13_1
L13_1 = "설령, 어느 날 갑자기 이곳에 초인이 떨어져서 고치들을 전부 토벌한다고 해도."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "たとえある日、ここにいきなり超人が降ってきて、繭をすべて討伐してくれたとしてもだ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Even if, one day, a superhuman just appeared in this world and exterminated all of the cocoons."
L12_1.m_Talk_ENG = L13_1
L13_1 = "就算是某天這個世界突然出現一個超人，消滅掉所有的繭。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ถึงแม้ว่าวันหนึ่งจะมียอดมนุษย์ปรากฏตัวขึ้นในโลกนี้ และทำลายรังไหมเนฟิลไปหมดก็ตาม  "
L12_1.m_Talk_THA = L13_1
L13_1 = "Ngay cả khi, một ngày nào đó, một siêu nhân xuất hiện trên thế giới này và tiêu diệt tất cả những chiếc kén."
L12_1.m_Talk_VTN = L13_1
L13_1 = "就算是某天这个世界突然出现一个超人，消灭了所有的茧。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Auch wenn eines Tages plötzlich ein Übermensch auf dieser Welt auftauchen und alle Kokons ausrotten würde."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Même si, un jour, un surhomme apparaissait comme par enchantement dans ce monde et exterminait tous les cocons..."
L12_1.m_Talk_FRA = L13_1
