L14_1.m_CharScale = L15_1
L14_1.m_CharScaleTime = 0.01
L15_1 = "곧 그 초인조차 감당할 수 없는, 또 다른 형태의 멸망이 닥쳐올 뿐이겠지."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "すぐにその超人ですら太刀打ちできない、また別の形の滅亡の危機が訪れるだけだ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Destruction will come in a different form, one that even this superhuman cannot handle."
L14_1.m_Talk_ENG = L15_1
L15_1 = "滅亡也會馬上以連超人都無能為力的形態來到。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "สุดท้ายการทำลายก็จะขึ้นขึ้นอีกในเหตุการณ์ใดเหตุการณ์หนึ่ง แม้แต่ยอดมนุษย์ก็ไม่อาจรับมือได้"
L14_1.m_Talk_THA = L15_1
L15_1 = "Sự hủy diệt sẽ đến dưới một hình thức khác, một hình thức mà ngay cả siêu nhân này cũng không thể xử lý được."
L14_1.m_Talk_VTN = L15_1
L15_1 = "也马上就会有连超人都无能为力的其他形态的灭亡到来。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "So würde schon bald eine andere Art von Zerstörung kommen, mit der selbst dieser Übermensch nicht fertigwerden könnte."
L14_1.m_Talk_DEU = L15_1
L15_1 = "La destruction de ce monde se présenterait sous une forme différente, une forme contre laquelle ce surhomme ne pourrait rien faire."
L14_1.m_Talk_FRA = L15_1
