L15_1.m_CharScale = L16_1
L15_1.m_CharScaleTime = 0.01
L16_1 = "침식률에 의한 인과결정은 무슨 억지를 쓰더라도 결과에 과정을 끼워 맞출 테니까."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "侵食率による因果決定においては、どう足掻いたとしても、過程は結果の辻褄合わせに過ぎない。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Causality determined by Corruption rate will force the process to fit the outcome regardless of how."
L15_1.m_Talk_ENG = L16_1
L16_1 = "這是因侵蝕率而決定的因果關係，不管怎麼頑強抵抗，結果都不會改變。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "สาเหตุที่กำหนดอัตราการคอรัปต์จะได้กำหนดผลลัพธ์ที่เหมาะสมออกมาได้ ไม่ว่าจะเกิดอะไรขึ้นก็ตาม"
L15_1.m_Talk_THA = L16_1
L16_1 = "Quan hệ nhân quả được xác định bởi Tỷ lệ Ăn Mòn sẽ buộc quá trình phù hợp với kết quả bất kể bằng cách nào."
L15_1.m_Talk_VTN = L16_1
L16_1 = "这是因侵蚀率而决定的因果关系，不管怎么负隅顽抗，结果都不会改变。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Die durch die Verderbnisrate bestimmte Kausalität zwingt den Prozess dazu, sich dem Ergebnis anzupassen, unabhängig davon, wie unnatürlich es auch sein mag."
L15_1.m_Talk_DEU = L16_1
L16_1 = "La causalité déterminée par le taux de Corruption obligera le processus à s'adapter au résultat, d'une façon ou d'une autre."
L15_1.m_Talk_FRA = L16_1
