L22_1 = "EXILER_ACT2_INTERUDE1@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5500201
L21_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "COMMANDER_EXILER_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "자네들은 지난 크로스로드 작전으로 한번 세계를 구했다고 했지?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "君たちは、以前のクロスロード作戦で一度世界を救ったと言ったな？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "You told me that you saved this world during Operation Crossroads, right?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "你之前告訴我，十字路口作戰拯救過一次這個世界吧？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "คุณเพิ่งบอกฉันว่า..คุณกอบกู้โลกในระหว่างที่ทำปฏิบัติการทางแยกใช่ไหม?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Cô bảo mình đã cứu thế giới này trong Tác Chiến Giao Lộ, phải không?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "你之前告诉我，十字路口作战拯救过一次这个世界吧？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Du hast mir doch erzählt, dass du diese Welt während der Operation „Scheideweg“ gerettet hast, oder?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Tu m'avais dit que tu avais sauvé ce monde pendant l'opération Carrefour, n'est-ce pas ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EXILER_ACT2_INTERUDE1@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5500201
L22_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "COMMANDER_EXILER_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "하지만 그렇기에, 자네들의 세계를 끝내기 위해 그 새하얀 그림자가 나타난 거야."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "しかし、だからこそ君たちの世界を終わらせるために、あの真っ白なシャドウが現れたんだ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Because of that, the white Shadow has appeared to finish this world."
L22_1.m_Talk_ENG = L23_1
L23_1 = "但也因此，為了毀滅你們的世界，出現了白色暗影。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เพราะเหตุนี้ ไวท์แชโดว์ จึงปรากฎตัวขึ้นแล้วออกมาทำลายโลกใบนี้ไง"
L22_1.m_Talk_THA = L23_1
L23_1 = "Chính vì thế mà Cái Bóng trắng đã xuất hiện để kết thúc thế giới này."
L22_1.m_Talk_VTN = L23_1
L23_1 = "但也因此，为了毁灭你们的世界，出现了白色暗影。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Aus diesem Grund scheint der weiße Schatten in dieser Welt aufgetaucht zu sein."
L22_1.m_Talk_DEU = L23_1
L23_1 = "C'est pour ça que l'Ombre blanche est apparue afin de mettre fin à ce monde."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EXILER_ACT2_INTERUDE1@123#Talk"
