L23_1.m_fWaitTime = 0
L24_1 = "COMMANDER_EXILER_NULL_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "기적과 기적이 겹쳐, 끝내 그 새하얀 그림자를 쓰러트린다고 해도."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "奇跡に奇跡が重なって、最終的にあの真っ白なシャドウを倒すことができたとしても。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Even if by some miracle, you do defeat the white Shadow..."
L23_1.m_Talk_ENG = L24_1
L24_1 = "哪怕奇蹟再次出現，最後打敗了那個白色暗影。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ถึงแม้ว่าคุณจะเอาชนะไวท์แชโดว์ไปด้วยปาฏิหาริย์ก็ตาม..."
L23_1.m_Talk_THA = L24_1
L24_1 = "Thậm chí bằng một phép màu nào đó cô cũng đánh bại được Cái Bóng trắng..."
L23_1.m_Talk_VTN = L24_1
L24_1 = "哪怕奇迹再次出现，最后打败了那个白色暗影。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Auch wenn du wie durch ein Wunder den weißen Schatten besiegen würdest ..."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Même si par miracle, vous parveniez à l'éliminer..."
L23_1.m_Talk_FRA = L24_1
