L26_1.m_CharScale = L27_1
L26_1.m_CharScaleTime = 0.01
L27_1 = "그 뒤를 기다리고 있는 건 희망 같은 게 아니야. 또 다른 형태의 절망일 뿐이지."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "その先に待っているものは決して希望などではない。また違った形の絶望があるのみだ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "What lies beyond is not hope. It will be despair in a different form."
L26_1.m_Talk_ENG = L27_1
L27_1 = "那之後等待你們的也不會是希望，而是另一種形態的絕望。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "สิ่งที่อยู่ไกลนั่นไม่ใช่ความหวัง แต่มันเป็นความสิ้นหวังที่แตกต่างตางหากล่ะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Thứ nằm ngoài tầm với không phải là hy vọng. Nó sẽ là sự tuyệt vọng ở dạng khác."
L26_1.m_Talk_VTN = L27_1
L27_1 = "那之后等待你们的也不会是希望，而是另一种形态的绝望。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "So würde dich danach keine Hoffnung erwarten, sondern nur eine andere Form der Verzweiflung."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Vous ne trouverez aucun salut, seulement du désespoir sous une autre forme."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
