L30_1 = "EXILER_ACT2_INTERUDE1@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 5500201
L29_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_HATE"
L29_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L29_1.m_Pos = "C"
L29_1.m_Crash = 10
L30_1 = "목숨을 건 그때의 작전이, 대원들의 숭고한 희생이! 그들이 벌어준 소중한 시간이!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "命を賭けたあの時の作戦が、隊員たちの崇高なる犠牲が！　彼らが稼いでくれた大切な時間が！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "The operation where we risked our lives, the soldiers' noble sacrifices! The precious time they bought us!!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "那場賭上性命的作戰，隊員們崇高的犧牲！還有他們爭取來的寶貴時間！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "แล้วปฏิบัติการที่เสี่ยงชีวิต กับการเสียสละของเหล่าทหารเราล่ะ! "
L29_1.m_Talk_THA = L30_1
L30_1 = "Tác chiến mà chúng tôi đã liều mạng, sự hy sinh cao cả của những người lính! Thời gian quý báu họ đã để lại cho chúng tôi!!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "那场赌上性命的作战，队员们崇高的牺牲！还有他们争取来的宝贵时间！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Die Operation, bei der wir unser Leben riskiert haben, die edlen Opfer der Soldaten! Die kostbare Zeit, die sie uns verschafft haben!!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Cette opération pour laquelle nous avons risqué nos vies, les nobles sacrifices des soldats ! Ce temps précieux qu'ils nous ont octroyé !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EXILER_ACT2_INTERUDE1@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5500201
L30_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L30_1.m_Pos = "C"
L30_1.m_Crash = 20
L31_1 = "어차피 처음부터 멸망이란 걸 피할 수 없는 거니까, 전부 무가치한 발버둥이었다고!?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "結局滅亡することは最初から決まっているから、全部無駄な悪足掻きだったって言うの！？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "It was all in vain?! Because this world was doomed from the start?!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "因為無論如何都無法避免的滅亡，就全都淪為無謂的掙扎嗎？！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "งั้นทุกอย่างมันก็ไร้ความหมายสิ! เพราะแท้จริงแล้วโลกนี้ก็ถูกกำหนดมาตั้งแต่ต้นแล้ว?!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tất cả đều vô ích sao?! Bởi vì thế giới này đã bị diệt vong ngay từ đầu?!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "因为无论如何都无法避免的灭亡，就全部沦为了无谓的挣扎吗？！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Das alles soll umsonst gewesen sein?! Weil diese Welt sowieso von Anfang an dem Untergang geweiht war?!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Tout ça était en vain ?! Parce que ce monde était condamné depuis le début ?!"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
