L32_1 = 40
L31_1.m_Crash = L32_1
L32_1 = "웃기지 마!! 당신이 뭘 안다고 그딴 소리를 하는 거야!!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ふざけないでよ！！　あなたにどうしてそんなことが言えるの！！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "You're wrong!! You have no right to say any of that!!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "真可笑！！你憑什麼這樣說！！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เธอคิดผิดแล้วแอนโทนอฟ!! เธอไม่มีสิทธิ์บอกว่ามันเช่นนี้!!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Cô sai rồi!! Cô không có quyền nói bất cứ điều gì như thế!!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "别搞笑了！！你凭什么这样说！！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Dass ich nicht lache!! Sie haben doch überhaupt keine Ahnung!!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Vous vous trompez ! Vous n'avez pas le droit de dire ça !"
L31_1.m_Talk_FRA = L32_1
