L34_1 = "UNIT_IDLE"
L33_1.m_Face = L34_1
L34_1 = "COMMANDER_EXILER_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L33_1.m_Crash = 10
L34_1 = "우리가 대체 몇 번이나 우리 세계를 구했다고 생각하나."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "我々が何度自分たちの世界を救ったかわかるか。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "How many times do you think we saved our world?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "你以為我們拯救過多少次我們的世界？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "คุณคิดว่าเรากอบกู้โลกของเรากี่ครั้งแล้ว?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cô nghĩ chúng tôi đã cứu thế giới của chúng tôi bao nhiêu lần rồi?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "你以为我们又拯救了多少次我们的世界呢？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Was denkst, wie oft wir schon unsere Welt gerettet haben?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Combien de fois penses-tu que nous avons sauvé notre monde ?"
L33_1.m_Talk_FRA = L34_1
