L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5500201
L37_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "UNIT_IDLE"
L37_1.m_Face = L38_1
L38_1 = "COMMANDER_EXILER_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "L"
L37_1.m_Pos = L38_1
L38_1 = "우리 세계는 자네의 세계보다 훨씬 진보된 세계였네."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "我々の世界は、君たちの世界よりも遥かに進歩していた。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Our world was far more advanced than yours is."
L37_1.m_Talk_ENG = L38_1
L38_1 = "我們的世界比你們的要先進發達許多。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "โลกของเราก้าวหน้าไปไกลกว่าที่คุณรู้จักมากซะอีก"
L37_1.m_Talk_THA = L38_1
L38_1 = "Thế giới của chúng tôi tiên tiến hơn thế giới của cô rất nhiều."
L37_1.m_Talk_VTN = L38_1
L38_1 = "我们的世界比你们的要先进发达许多。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Unsere Welt war weitaus fortschrittlicher als deine."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Notre monde était beaucoup plus avancé que le vôtre."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EXILER_ACT2_INTERUDE1@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 5500201
L38_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "COMMANDER_EXILER_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "L"
L38_1.m_Pos = L39_1
L39_1 = "우리 대원들은 전원, 텔로미어를 조작해 노화를 늦춰 언제나 전성기인 육체로 싸웠고."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "隊員は全員、テロメアの操作によって老化を遅らせ、常に全盛期の肉体で戦うことができた。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "We altered our telomeres to slow the rate of aging, allowing us to fight in our prime physical condition."
L38_1.m_Talk_ENG = L39_1
L39_1 = "所有隊員都可以透過控制端粒來延緩衰老，始終以全盛期的身體參與戰鬥。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เราเปลี่ยนเทโลเมียร์เพื่อช่วยชะลอความแก่ เพื่อช่วยให้เราสามารถต่อสู้ในสภาพร่างกายที่สมบูรณ์และแข็งแรงได้"
L38_1.m_Talk_THA = L39_1
L39_1 = "Chúng tôi đã thay thế tất cả telomeres của mình để làm chậm tốc độ lão hóa, cho phép chúng tôi chiến đấu trong tình trạng thể chất tốt nhất."
L38_1.m_Talk_VTN = L39_1
L39_1 = "所有队员都可以通过控制端粒来延缓衰老，始终以全盛期的身体参与战斗。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Wir haben unsere Telomere verändert, um den Alterungsprozess zu verlangsamen, sodass wir in bester körperlicher Verfassung kämpfen konnten."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Nous avons modifié nos télomères afin de ralentir notre vieillissement, nous permettant de nous battre tout en conservant notre forme physique."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EXILER_ACT2_INTERUDE1@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 5500201
L39_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "COMMANDER_EXILER_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "L"
L39_1.m_Pos = L40_1
L40_1 = "닥치는 대로 이면세계를 뒤져 발견한 고유 무장들을 분석하고 복제해서 그와 대등한 화력의 전술 무장을 양산할 수 있었지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "手当たり次第に裏世界を探索し、発見した数々の固有武装を分析、複製して、それと対等な火力を持つ戦術武装を量産することさえできた。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "We scoured Counterside for Unique Gear, which we analyzed and duplicated to mass-produce Tactical Gear of equal firepower."
L39_1.m_Talk_ENG = L40_1
L40_1 = "並且可以隨意探索異界，分析發現的專屬裝備，複製並量產與他火力相當的戰術裝備。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เราค้นหาเคาน์เตอร์ไซด์และทำอุปกรณ์เหมาะสมเฉพาะคน ทั้งวิเคราะห์และวิจัยเพื่อผลิตอุปกรณ์ทางยุทธวิธีจำนวนมากที่มีพลังมหาศาล"
L39_1.m_Talk_THA = L40_1
L40_1 = "Chúng tôi lùng sục Counterside để tìm Trang Bị Độc Nhất, thứ mà chúng tôi đã phân tích và sao chép để sản xuất hàng loạt Trang Bị Chiến Lược với hỏa lực tương đương."
L39_1.m_Talk_VTN = L40_1
L40_1 = "并且可以随意探索异界，分析发现的专属装备，复制并量产与它火力相当的战术武装。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Indem wir Counterside durchforstet und die gefundene Spezialausrüstung analysiert und reproduziert haben, konnten wir taktische Waffen mit gleicher Feuerkraft in Massenproduktion herstellen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Nous avons parcouru le Contremonde à la recherche d'équipements uniques, que nous avons analysés et copiés afin de produire en masse des équipements tactiques avec une puissance de feu équivalente."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
