L42_1 = "EXILER_ACT2_INTERUDE1@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 5500201
L41_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "UNIT_IDLE"
L41_1.m_Face = L42_1
L42_1 = "COMMANDER_EXILER_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "L"
L41_1.m_Pos = L42_1
L42_1 = "하지만 우리 중 아무도 눈치채지 못했어."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "しかし、我々の世界の誰ひとりとして、気付ける者はいなかったのだ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "But none of us ever sensed it coming."
L41_1.m_Talk_ENG = L42_1
L42_1 = "但我們當中沒有任何人意識到。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "แต่ไม่มีใครทำมันได้"
L41_1.m_Talk_THA = L42_1
L42_1 = "Nhưng không ai trong chúng tôi từng cảm nhận được nó đến."
L41_1.m_Talk_VTN = L42_1
L42_1 = "但我们当中没有任何人意识到。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Aber keiner von uns hätte jemals damit gerechnet, was wir dadurch verursachen würden."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Mais aucun de nous n'a pu prévoir ce qui allait se passer."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EXILER_ACT2_INTERUDE1@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5500201
L42_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_DESPAIR"
L43_1 = "COMMANDER_EXILER_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "L"
L42_1.m_Pos = L43_1
L43_1 = "그런 짓을 하면…… 그 세계의 수준에 맞지 않는 기술력을 쓰면, 오히려 세계의 침식률을 끌어올리게 된다는 걸 말이야."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "そんなことをしてしまえば……自分たちの世界の技術レベルを超えるテクノロジーを使ってしまったら、むしろその世界の侵食率を引き上げてしまうということに。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "By doing so... By using technology too advanced for the world, it would increase the world's Corruption rate in return."
L42_1.m_Talk_ENG = L43_1
L43_1 = "這樣做的後果……使用與這個世界的水準不匹配的技術，反而會提高世界的侵蝕率。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เพราะการทำแบบนี้... ในการใช้เทคโนโลยีที่ล้ำหน้าเกินไปบนโลก มันจะเพิ่มอัตราการคอร์รัปต์ของโลกเราเพิ่มขึ้น"
L42_1.m_Talk_THA = L43_1
L43_1 = "Khi làm như vậy... Bằng cách sử dụng công nghệ quá tiên tiến đối với thế giới, đổi lại, nó sẽ làm tăng tỷ lệ Ăn Mòn."
L42_1.m_Talk_VTN = L43_1
L43_1 = "这样做的后果……使用与这个世界的水准不匹配的技术，反而会提高世界的侵蚀率。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Dadurch dass ... wir Technologien eingesetzt haben, die für unsere Welt zu fortschrittlich waren, wurde unweigerlich die Verderbnisrate dieser Welt erhöht."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Utiliser une technologie trop avancée pour le monde conduit inexorablement à l'augmentation du taux de Corruption de celui-ci."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EXILER_ACT2_INTERUDE1@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 5500201
L43_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "UNIT_IDLE"
L43_1.m_Face = L44_1
L44_1 = "COMMANDER_EXILER_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "L"
L43_1.m_Pos = L44_1
L44_1 = "결국 우리는 세계를 구할수록, 몇 번이나 더 큰 절망에 마주할 수밖에 없었네."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "結局我々は世界を救えば救うほど、さらに大きな絶望に幾度となく直面するしかなかった。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Ultimately, the more we saved our world, the more despair we were faced with time and time again."
L43_1.m_Talk_ENG = L44_1
L44_1 = "到最後，我們越是拯救世界，越會面臨更多更大的絕望。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "สุดท้ายถึงเรากอบกู้โลกมากเท่าไร พวกเราเองก็ยิ่งเผชิญกับความสิ้นหวังครั้งแล้วครั้งเล่าไงหล่ะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Cuối cùng, chúng tôi càng cứu thế giới của mình, chúng tôi càng phải đối mặt với sự tuyệt vọng hết lần này đến lần khác."
L43_1.m_Talk_VTN = L44_1
L44_1 = "到最后，我们越是拯救世界，越会面临更多更大的绝望。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Je mehr wir letztendlich unsere Welt gerettet haben, mit desto mehr Verzweiflung waren wir konfrontiert."
L43_1.m_Talk_DEU = L44_1
L44_1 = "En fin de compte, plus nous sauvions notre monde et plus nous faisions face au désespoir, encore et encore."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EXILER_ACT2_INTERUDE1@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 5500201
L44_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "COMMANDER_EXILER_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "L"
L44_1.m_Pos = L45_1
L45_1 = "바로 지금 자네들의 세계처럼 말이지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "まさに今の君たちの世界のようにだ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Just like what is happening to your world."
L44_1.m_Talk_ENG = L45_1
L45_1 = "就和你們的世界一樣。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เหมือนสิ่งที่เพิ่งเกิดขึ้นกับโลกของคุณยังไง"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cũng giống như những gì đang xảy ra với thế giới của cô."
L44_1.m_Talk_VTN = L45_1
L45_1 = "就和现在你们的世界一样。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Es ist genau das Gleiche, was gerade mit deiner Welt passiert."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Exactement comme ce qui arrive à votre monde."
L44_1.m_Talk_FRA = L45_1
