L47_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L47_1.m_Pos = "C"
L48_1 = "그래서 도망친 건가, 결국."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "それで最後には逃げたというの。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "So you ultimately fled."
L47_1.m_Talk_ENG = L48_1
L48_1 = "所以你們就逃跑了嗎？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "งั้นเธอก็จะหนีมันไปงั้นหรอ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Vì vậy, cuối cùng cô đã bỏ trốn."
L47_1.m_Talk_VTN = L48_1
L48_1 = "所以你们就逃跑了吗，最终。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Also sind Sie letztendlich geflohen."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Vous avez donc choisi de fuir ?"
L47_1.m_Talk_FRA = L48_1
