L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 5500201
L50_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "UNIT_IDLE"
L50_1.m_Face = L51_1
L51_1 = "COMMANDER_EXILER_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "L"
L50_1.m_Pos = L51_1
L51_1 = "그래. 꼴사납지만 그게 우리가 할 수 있는 최선이었으니까."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "そうだ。惨めではあるが我々が選べる最善だったからな。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Correct. Although it leaves a bad taste in my mouth, it was the best we could do."
L50_1.m_Talk_ENG = L51_1
L51_1 = "沒錯。雖然有些難看，但那是我們所能做的上上策了。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ใช่ถูกต้อง แม้ว่าเราต้องทิ้งทุกอย่างไป มันคือสิ่งเดียวที่ดีที่สุดที่เราทำได้"
L50_1.m_Talk_THA = L51_1
L51_1 = "Chính xác. Mặc dù rất cay đắng nhưng đó là điều tốt nhất chúng tôi có thể làm."
L50_1.m_Talk_VTN = L51_1
L51_1 = "没错。虽然有些难看，但那是我们所能做的最优选择了。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "So ist es. Obwohl ich mich schäme, es zuzugeben, war es dennoch das Beste, was wir tun konnten."
L50_1.m_Talk_DEU = L51_1
L51_1 = "En effet. Bien que cela me laisse un certain goût amer en bouche, c'était la seule solution qu'il nous restait."
L50_1.m_Talk_FRA = L51_1
