L2_1 = "EXILER_ACT2_INTERUDE1@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 5500201
L1_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_DESPAIR"
L2_1 = "COMMANDER_EXILER_NULL_NULL"
L1_1.m_CharStrID = L2_1
L2_1 = "L"
L1_1.m_Pos = L2_1
L2_1 = "우리 세계가 간신히 축적한 기술을 보존해, 다음 번 인류에게 전달하는 것."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "我々の世界が辛うじて蓄積した技術を、次の人類に伝えること。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "To transfer the technology we barely accumulated in our world to the next human race."
L1_1.m_Talk_ENG = L2_1
L2_1 = "保護我的世界好不容易累積下來的技術，傳達給下一批人類。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "เพื่อส่งต่อเทคโนโลยีของเรา ที่เราเองแทบไม่ได้เก็บไว้ใช้เอง ให้เผ่าพันธุ์มนุษย์รุ่นต่อๆไปได้ใช้"
L1_1.m_Talk_THA = L2_1
L2_1 = "Để chuyển giao công nghệ mà chúng tôi đã khó khắn tích lũy được trong thế giới của mình cho loài người tiếp theo."
L1_1.m_Talk_VTN = L2_1
L2_1 = "保护我的世界好不容易积攒下来的技术，传达给下一批人类。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Um die Technologie, die unsere Welt angesammelt hat, zu bewahren und an die nächste Generation der Menschheit weiterzugeben."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Transmettre la technologie que nous avions réussi à accumuler dans notre monde aux prochains humains..."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EXILER_ACT2_INTERUDE1@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 5500201
L2_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "UNIT_IDLE"
L2_1.m_Face = L3_1
L3_1 = "COMMANDER_EXILER_NULL_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "L"
L2_1.m_Pos = L3_1
L3_1 = "그것이 우리에게, 나에게 주어진 마지막 사명이네."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "それが我々に、私に与えられた最後の使命だ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "That is the final mission that was given to me, and to us."
L2_1.m_Talk_ENG = L3_1
L3_1 = "這就是賦予我們，賦予我的最後使命。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "นั่นคือภารกิจสุดท้ายที่ฉันได้รับมอบหมายมา"
L2_1.m_Talk_THA = L3_1
L3_1 = "Đó là nhiệm vụ cuối cùng đã được trao cho tôi, và cho chúng ta."
L2_1.m_Talk_VTN = L3_1
L3_1 = "这就是赋予我们、赋予我的最后使命。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Das ist die letzte Mission, die mir und uns anvertraut wurde."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Voilà la dernière mission qui nous a été confiée, à moi et aux autres."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EXILER_ACT2_INTERUDE1@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 5500201
L3_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "UNIT_IDLE"
L3_1.m_Face = L4_1
L3_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L4_1 = "R"
L3_1.m_Pos = L4_1
L4_1 = "그렇게 도착한 세계가 우리 세계였다는 뜻인가요?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "そうしてたどり着いたのが、こちらの世界だったというわけですか？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "And the world you arrived just happened to be ours?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "然後就碰巧來到了我們的世界？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แล้วโลกที่เธอมาถึง ก็บังเอิญเกิดขึ้นกับเรางั้นเหรอ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Và cô chỉ tình cờ đến thế giới của chúng tôi?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "然后就碰巧来到了，我们的世界？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Und die Welt, in der Sie gelandet sind, war rein zufällig unsere?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Et le monde dans lequel vous êtes arrivés était en fait le nôtre ?"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EXILER_ACT2_INTERUDE1@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 5500201
L4_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_DESPAIR"
L5_1 = "COMMANDER_EXILER_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "L"
L4_1.m_Pos = L5_1
L4_1.m_Crash = 10
L5_1 = "그렇네."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "そうだ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Yes."
L4_1.m_Talk_ENG = L5_1
L5_1 = "是。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ถูกต้อง"
L4_1.m_Talk_THA = L5_1
L5_1 = "Đúng."
L4_1.m_Talk_VTN = L5_1
L5_1 = "是。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Ja."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Oui."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EXILER_ACT2_INTERUDE1@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5500201
L5_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "UNIT_IDLE"
L5_1.m_Face = L6_1
L6_1 = "COMMANDER_EXILER_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "L"
L5_1.m_Pos = L6_1
L6_1 = "하지만 안타깝게도 침식률이 이 정도까지 진행된 세계는 더는 회생 가능성이 없어."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "しかし残念ながら、侵食率がここまで上昇している世界はもはや助かる見込みがない。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Unfortunately, this world is no longer recoverable, looking at how much the Corruption rate has already progressed."
L5_1.m_Talk_ENG = L6_1
L6_1 = "可惜的是，侵蝕率如此高的世界，不存在重生的可能性。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "น่าเสียดายที่โลกนี้ไม่สามารถกู้คืนได้อีกต่อไป หากดูจากอัตราการคอร์รัปชันที่หนักเกินไป"
L5_1.m_Talk_THA = L6_1
L6_1 = "Đáng tiếc, thế giới này không còn khôi phục được nữa, nhìn tỷ lệ Ăn Mòn đã đến mức nào rồi."
L5_1.m_Talk_VTN = L6_1
L6_1 = "可惜的是，侵蚀率如此高的世界，不存在重生的可能性。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Leider kann sich diese Welt nicht mehr erholen, wenn man bedenkt, wie weit die Verderbnisrate bereits fortgeschritten ist."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Malheureusement, un monde ayant un tel taux de Corruption n'a plus aucun espoir de survie."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EXILER_ACT2_INTERUDE1@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 5500201
L6_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "COMMANDER_EXILER_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "L"
L6_1.m_Pos = L7_1
L7_1 = "발버둥 칠수록 더욱 더 깊은 절망의 늪에 빠질 뿐이겠지."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "足掻けば足掻くほど、より深い絶望の沼に沈んでいくだけだろう。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "The more you fight it, the deeper you will fall into the pit of despair."
L6_1.m_Talk_ENG = L7_1
L7_1 = "越是垂死掙扎，越會陷入更深的絕望泥沼。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ยิ่งสู้ก็ยิ่งตกหลุมแห่งความสิ้นหวัง"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cô càng chống lại nó, cô sẽ càng rơi sâu vào hố sâu tuyệt vọng."
L6_1.m_Talk_VTN = L7_1
L7_1 = "越是垂死挣扎，越会陷入更深的绝望泥沼。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Je mehr du dagegen ankämpfst, desto tiefer wirst du in den Abgrund der Verzweiflung stürzen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Plus vous luttez et plus vous tombez profondément dans la spirale du désespoir."
L6_1.m_Talk_FRA = L7_1
