L9_1 = "EXILER_ACT2_INTERUDE1@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 5500201
L8_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_HATE"
L8_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L8_1.m_Pos = "C"
L8_1.m_Crash = 20
L9_1 = "그래서 다 포기하고 결과를 받아들이라고?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "だから、すべてを諦めて結果を受け入れろと？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "So you want us to just give up and accept it?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "所以你的意思是想讓我們放棄一切，接受這個結局?"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แล้วเธอต้องการให้เรายอมแพ้ และยอมรับความจริงงั้นหรอ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Vì vậy, cô muốn chúng tôi cứ từ bỏ và chấp nhận nó?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "所以你的意思是想让我们放弃一切，接受这个结局?"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Sie möchten also, dass wir einfach aufgeben und das Ergebnis akzeptieren?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Alors vous voulez que nous abandonnions et acceptions notre sort ?"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EXILER_ACT2_INTERUDE1@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 5500201
L9_1.m_CutScenStrID = "EXILER_ACT2_INTERUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L9_1.m_Pos = "C"
L9_1.m_Crash = 10
L10_1 = "침식률인지, 뭔지 때문에…… 운명은 바꿀 수 없으니까……."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "侵食率だか何だかのせいで……運命は変えられないから……"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Because fate can't be changed... because of this Corruption rate you keep talking about...?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "因為侵蝕率什麼的……因為命運無法被改變……"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เพียงแค่เชื่อว่าโชคชะตาไม่อาจเปลี่ยนแปลงมันได้...เพราะอัตราการคอร์รัปชั่นบ้าๆที่เธอพูดถึง...?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Bởi vì số phận không thể thay đổi... vì tỷ lệ Ăn Mòn mà cô cứ nhắc tới...?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "因为侵蚀率什么的……因为命运无法被改变……"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Weil das Schicksal ... wegen dieser Verderbnisrate nicht verändert werden kann ...?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Tout ça parce que le destin ne peut pas être changé... à cause de ce taux de Corruption dont vous n'arrêtez pas de parler..."
L9_1.m_Talk_FRA = L10_1
