L11_1 = 40
L10_1.m_Crash = L11_1
L11_1 = "어차피 멸망이라는 건 막을 수 없으니까! 얌전히 죽는 걸 기다리라는 건가요?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "どうせ滅ぶ運命だから！　大人しく最期の瞬間を待てということですか？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "You want us to sit around and wait for our doom since there's no way to stop the collapse?!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "反正滅亡無法阻止！所以要乖乖等死嗎？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เธอจะให้เราอยู่เฉยๆแล้วรอชะตากรรมงั้นหรอ เพราะเชื่อว่าไม่มีทางแก้ไขได้สิ!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Cô muốn chúng tôi ngồi đó và chờ đợi sự diệt vong đến với mình vì không có cách nào để ngăn chặn sự sụp đổ?!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "反正灭亡无法阻止！所以要乖乖等死吗？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Sie wollen also, dass wir nur herumsitzen und auf unseren Tod warten, da es keine Möglichkeit gibt, die Zerstörung zu stoppen?!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Vous voulez que nous restions les bras croisés en attendant notre destin car il n'y a aucun moyen d'arrêter l'effondrement du monde ?!"
