L13_1.m_CharScale = L14_1
L13_1.m_CharScaleTime = 0.01
L14_1 = "소령, 자네는 기지를 떠나기 전 기억을 잃은 내게 선택지를 주었지?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "少佐、君は基地を離れる前、記憶喪失の私に選択肢を与えてくれただろう？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Major, you gave me, a person who lost her memories, a choice before you left base. Remember that?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "少校，你離開基地之前，給了失憶的我一個選擇吧？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "สารวัตร คุณ เคยให้ทางเลือกฉัน แกคนที่สูญเสียความทรงจำ ก่อนที่คุณจะออกจากฐานทัพ คุณจำมันได้ไหม?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Thiếu tá, cô đã cho tôi, một người mất trí nhớ, một sự lựa chọn trước khi cô rời căn cứ. Nhớ chứ?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "少校，你离开基地之前，给了失忆的我一个选择吧？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Major, du hast mir, einer Person, die ihre Erinnerungen verloren hat, eine Wahl gegeben, bevor du die Basis verlassen hast. Erinnerst du dich daran?"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Major, tu m'as demandé de faire un choix avant de quitter la base, à moi qui avais perdu mes souvenirs. Tu t'en souviens ?"
L13_1.m_Talk_FRA = L14_1
