L19_1 = "수없이 분화한 평행세계 중에서 단 하나의 세계."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "無数に分岐している平行世界の中でたったひとつ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Of all the countless parallel universes, there is one world."
L18_1.m_Talk_ENG = L19_1
L19_1 = "在無數分化的平行世界中，僅有一個世界。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ในจักรวาลมีโลกที่คู่ขนานนับไม่ถ้วน แต่หนึ่งในนั้นมีโลกแค่ใบเดียว"
L18_1.m_Talk_THA = L19_1
L19_1 = "Trong tất cả vô số vũ trụ song song, có một thế giới."
L18_1.m_Talk_VTN = L19_1
L19_1 = "在无数分化的平行世界中，仅有一个世界。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Von all den unzähligen Paralleluniversen gibt es eine Welt."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Parmi tous les innombrables univers parallèles, il existe un monde."
