L20_1 = "세계의 침식률을 관리하는 <color=#ffd34c>관리국</color>이라는 기관이 존재하는 세계가 있다네."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "世界の侵食率を管理する<color=#ffd34c>管理局</color>という機関が存在する世界がある。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "A world where the Corruption rate is managed by an institution called <color=#ffd34c>the Administration</color>."
L19_1.m_Talk_ENG = L20_1
L20_1 = "存在管理世界侵蝕率的組織，該組織名為<color=#ffd34c>管理局</color>。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "โลกที่มีอัตราการคอรัปต์จัดการโดยสถาบันที่เรียกว่า <color=#ffd34c>องค์การบริหารโลก</color>"
L19_1.m_Talk_THA = L20_1
L20_1 = "Một thế giới mà tỷ lệ Ăn Mòn được quản lý bởi một tổ chức gọi là <color=#ffd34c>Cục Quản Lý</color>."
L19_1.m_Talk_VTN = L20_1
L20_1 = "存在管理世界侵蚀率的机构，此机构名为<color=#ffd34c>管理局</color>。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Eine Welt, in der die Verderbnisrate von einer Institution namens <color=#ffd34c>Administration</color> verwaltet wird."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Un monde où le taux de Corruption est contrôlé par une institution appelée l'<color=#ffd34c>Administration</color>."
L19_1.m_Talk_FRA = L20_1
