L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "我々の本来の最終目的地はそこだった。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Our ultimate objective was to reach that world."
L20_1.m_Talk_ENG = L21_1
L21_1 = "原本是我們最終的目的地。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "และนั่นคือจุดประสงค์ที่เราจะต้องไปที่โลกนั้น "
L20_1.m_Talk_THA = L21_1
L21_1 = "Mục tiêu cuối cùng của chúng tôi từng là đến được thế giới đó."
L20_1.m_Talk_VTN = L21_1
L21_1 = "原本是我们最终的目的地。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Unser ultimatives Ziel war es, diese Welt zu erreichen."
