L22_1 = "관리국? 잠깐? 당신 방금 관리국이라고 했어?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "管理局？　待ってください。今管理局と言いましたか？"
