L22_1 = "องค์การบริหารโลก? ดะ เดี๋ยวนะ  นี่เธอเพิ่งพูดว่า \"องค์การบริหารโลกเหรอ? \""
L21_1.m_Talk_THA = L22_1
L22_1 = "Cục Quản Lý? Đợi đã. Có phải cô vừa nói \"Cục Quản Lý?\""
