L23_1.m_CharScale = L24_1
L23_1.m_CharScaleTime = 0.01
L24_1 = "이미 멸망이 확정된 이 세계에서는 아무것도 할 수 없고, 아무도 구할 수 없어."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "すでに滅亡が確定したこの世界では、手を打つことも、誰かを救うこともできない。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "In a world where destruction is determined, there is nothing you can do to save it or its people."
L23_1.m_Talk_ENG = L24_1
L24_1 = "在這個註定要滅亡的世界裡，什麼也做不了，什麼也拯救不了。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "โลกที่ถูกกำหนดการทำลายล้างไว้แล้ว ไม่มีประโยชน์ที่คุณจะช่วยโลกหรือผู้คนให้รอดพ้นไปได้"
L23_1.m_Talk_THA = L24_1
L24_1 = "Trong một thế giới mà sự hủy diệt đã được xác định, cô không thể làm gì để cứu nó hoặc người dân ở đó."
L23_1.m_Talk_VTN = L24_1
L24_1 = "在这个注定灭亡的世界里，什么也做不了，什么也拯救不了。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "In einer Welt, in der die Zerstörung bereits in Stein gemeißelt ist, gibt es nichts, was du tun kannst, um sie oder ihre Menschen noch zu retten."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Dans un monde dont la destruction est prédéterminée, on ne peut rien faire pour le sauver, lui ou ses habitants."
L23_1.m_Talk_FRA = L24_1
