L24_1.m_CharScale = L25_1
L24_1.m_CharScaleTime = 0.01
L25_1 = "어떤가, 소령? 나와 함께 관리국이 존재하는 세계로 나아가지 않겠나?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "どうだ、少佐？　私と共に管理局のある世界に行かないか？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "What will it be, Major? Will you join me and head to the world where the Administration exists?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "怎麼樣，少校？要和我一起前往管理局所在的世界嗎？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "สารวัตรคารินคุณคิดว่าไง? ถ้าฉันจะให้คุณเข้าร่วมทีมด้วยและเรามุ่งหน้าไปที่โลกขององค์การบริหารโลกอาศัยอยู่?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Lựa chọn là gì đây Thiếu tá? Cô sẽ tham gia cùng tôi và hướng đến thế giới nơi Cục Quản Lý tồn tại chứ?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "怎么样，少校？要和我一起前往管理局所在的世界吗？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Was wirst du nun tun, Major? Wirst du dich mir anschließen und in die Welt reisen, in der die Administration existiert?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Que vas-tu choisir, major ? Vas-tu me rejoindre et partir pour un monde où l'Administration existe ?"
